package com.acxiom.crm.opportunity;
import com.acxiom.crm.customer.*; import com.acxiom.crm.audit.AuditService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BeanPropertyBindingResult;
import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import java.time.LocalDate; import java.util.List;
@Controller public class OpportunityController {
 private final OpportunityRepository repo; private final CustomerRepository customers; private final OpportunityValidator validator; private final AuditService audit;
 private static final List<String> STAGES=List.of("Qualification","Proposal","Negotiation","Won","Lost");
 public OpportunityController(OpportunityRepository r,CustomerRepository c,OpportunityValidator v,AuditService a){repo=r;customers=c;validator=v;audit=a;}
 private void formData(Model m){m.addAttribute("customers",customers.findAll());m.addAttribute("stages",STAGES);m.addAttribute("today",LocalDate.now());}
 @GetMapping("/opportunities") public String list(Model m){var rows=repo.findAll();double pipeline=rows.stream().filter(o->!List.of("Won","Lost").contains(o.getStage())).mapToDouble(o->o.getAmount()==null?0:o.getAmount()).sum();double weighted=rows.stream().filter(o->!List.of("Won","Lost").contains(o.getStage())).mapToDouble(Opportunity::getWeightedValue).sum();m.addAttribute("opportunities",rows);m.addAttribute("pipeline",pipeline);m.addAttribute("weightedPipeline",weighted);return "opportunities";}
 @GetMapping("/opportunities/new") public String createForm(Model m){m.addAttribute("opportunity",new Opportunity());m.addAttribute("selectedCustomerId",null);formData(m);return "opportunity-form";}
 @PostMapping("/opportunities") public String create(@Valid @ModelAttribute("opportunity") Opportunity o,BindingResult r,@RequestParam(required=false) Long customerId,Model m){Customer c=customerId==null?null:customers.findById(customerId).orElse(null);if(c==null)r.rejectValue("customer","required","Please select a valid customer.");else o.setCustomer(c);String err=validator.validate(o);if(err!=null)r.reject("businessRule",err);if(r.hasErrors()){m.addAttribute("selectedCustomerId",customerId);formData(m);return "opportunity-form";}o.setStatus(status(o.getStage()));repo.save(o);audit.log("OPPORTUNITY","CREATE",o.getId(),"Created opportunity: "+o.getName());return "redirect:/opportunities";}
 @GetMapping("/opportunities/{id}/edit") public String edit(@PathVariable Long id,Model m){Opportunity o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));m.addAttribute("opportunity",o);m.addAttribute("selectedCustomerId",o.getCustomer().getId());formData(m);return "opportunity-form";}
 @PostMapping("/opportunities/{id}") public String update(@PathVariable Long id,@Valid @ModelAttribute("opportunity") Opportunity f,BindingResult r,@RequestParam(required=false) Long customerId,Model m){Opportunity o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Customer c=customerId==null?null:customers.findById(customerId).orElse(null);if(c==null)r.rejectValue("customer","required","Please select a valid customer.");else f.setCustomer(c);String err=validator.validate(f);if(err!=null)r.reject("businessRule",err);if(r.hasErrors()){m.addAttribute("selectedCustomerId",customerId);formData(m);return "opportunity-form";}o.setName(f.getName());o.setCustomer(c);o.setAmount(f.getAmount());o.setProbability(f.getProbability());o.setExpectedCloseDate(f.getExpectedCloseDate());o.setStage(f.getStage());o.setStatus(status(f.getStage()));o.setSource(f.getSource());o.setNotes(f.getNotes());repo.save(o);audit.log("OPPORTUNITY","UPDATE",o.getId(),"Updated opportunity: "+o.getName());return "redirect:/opportunities";}
 @PostMapping("/opportunities/{id}/delete") public String delete(@PathVariable Long id){repo.deleteById(id);audit.log("OPPORTUNITY","DELETE",id,"Deleted opportunity");return "redirect:/opportunities";}
 private String status(String s){return "Won".equals(s)?"WON":"Lost".equals(s)?"LOST":"OPEN";}
}
